-- Paired private query-only patch: parameterize the exact two NEWAR fiat raw joins.
-- No new helper/table/cache/trigger/queue/cron/index, timeout, hint or financial expression.
-- Atomic install/undo; all source metadata, other routines and prepared tokens stay equal.
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='500ms';
DO $pair$DECLARE r jsonb;p pg_proc%rowtype;old_count integer:=0;new_count integer:=0;definition text;metadata jsonb;other_before text;source_before text;tokens_before jsonb;d record;
 rows constant jsonb:=$pairs$[{"name":"parent","signature":"private.dashboard_admin_live_workorders(jsonb)","before":"    from newar_detail_days_v1 t join public.newar_detail_records n\n      on n.platform=t.platform and n.dataset='workorder'\n      and n.created_at>=(t.stat_date::timestamp at time zone t.timezone)\n      and n.created_at<((t.stat_date+1)::timestamp at time zone t.timezone)\n      and (t.launch_at is null or n.created_at>=t.launch_at)\n    where n.workorder_type in ('\u5b58\u6b3e\u672a\u5230\u8d26','\u5b58\u6b3e\u672a\u5230\u8d26\u81ea\u52a8\u5316')","after":"    from newar_detail_days_v1 t cross join lateral (\n      select n.* from public.newar_detail_records n\n      where n.platform=t.platform and n.dataset='workorder'\n        and n.created_at>=(t.stat_date::timestamp at time zone t.timezone)\n        and n.created_at<((t.stat_date+1)::timestamp at time zone t.timezone)\n        and (t.launch_at is null or n.created_at>=t.launch_at)\n        and n.workorder_type in ('\u5b58\u6b3e\u672a\u5230\u8d26','\u5b58\u6b3e\u672a\u5230\u8d26\u81ea\u52a8\u5316')\n      offset 0\n    ) n","oldBody":"813f5a871d33d24489616dc4cfa353a4","oldDefinition":"8cd605d971f46325ebe0d69b1c59dde7","newBody":"7fc5933fa0e9a7a754d5091c834f130f","newDefinition":"5bbd8c260981fb7f6346030bb9480852","metadataMD5":"9d7cf65632ec8e811a84eb1627c32184"},{"name":"unique","signature":"private.dashboard_admin_live_workorder_unique_totals(jsonb,jsonb)","before":"    from newar_targets t join public.newar_detail_platforms cfg on cfg.platform=t.platform\n    join public.newar_detail_records n on n.platform=t.platform and n.dataset='workorder'\n      and n.created_at>=(v_start::timestamp at time zone t.timezone)\n      and n.created_at<((v_end+1)::timestamp at time zone t.timezone)\n      and (t.launch_at is null or n.created_at>=t.launch_at)\n    where n.workorder_type in ('\u5b58\u6b3e\u672a\u5230\u8d26','\u5b58\u6b3e\u672a\u5230\u8d26\u81ea\u52a8\u5316')","after":"    from newar_targets t join public.newar_detail_platforms cfg on cfg.platform=t.platform\n    cross join lateral (\n      select n.* from public.newar_detail_records n\n      where n.platform=t.platform and n.dataset='workorder'\n        and n.created_at>=(v_start::timestamp at time zone t.timezone)\n        and n.created_at<((v_end+1)::timestamp at time zone t.timezone)\n        and (t.launch_at is null or n.created_at>=t.launch_at)\n        and n.workorder_type in ('\u5b58\u6b3e\u672a\u5230\u8d26','\u5b58\u6b3e\u672a\u5230\u8d26\u81ea\u52a8\u5316')\n      offset 0\n    ) n","oldBody":"7a0c9a592bca8642dcd60e685f5ee49c","oldDefinition":"ce7c3d92f1392c9ea879026f014c3dfe","newBody":"16796d0d63b57c610f1724df9a269992","newDefinition":"38e9496aa5f6716a2a54f0737f8d25bc","metadataMD5":"2a87d7a417c73abb5403fa1e60c0dd4c"}]$pairs$::jsonb;
BEGIN
 IF current_user<>'postgres'THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='workorder_parameterized_owner_required';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(rows)LOOP
  SELECT *INTO p FROM pg_proc WHERE oid=to_regprocedure(r->>'signature');
  IF p.oid IS NULL OR md5((to_jsonb(p)-'prosrc')::text)IS DISTINCT FROM r->>'metadataMD5'OR pg_get_userbyid(p.proowner)<>'postgres'
  THEN RAISE EXCEPTION'workorder_parameterized_metadata_drift: %',r->>'signature';END IF;
  IF md5(p.prosrc)=r->>'oldBody'AND md5(pg_get_functiondef(p.oid))=r->>'oldDefinition'THEN old_count:=old_count+1;
  ELSIF md5(p.prosrc)=r->>'newBody'AND md5(pg_get_functiondef(p.oid))=r->>'newDefinition'THEN new_count:=new_count+1;
  ELSE RAISE EXCEPTION'workorder_parameterized_body_drift: %',r->>'signature';END IF;
 END LOOP;
 IF old_count<>2 AND new_count<>2 THEN RAISE EXCEPTION'workorder_parameterized_mixed_state';END IF;
 FOR d IN SELECT *FROM(VALUES('private.prepared_aggregate_dependency_common(text)','36966b6e1e434eb6d5990e551f816b8e','1c8080bcc9742302e3cf5c11ef565c40'),('private.provider_snapshot_dependency_token(jsonb)','ccf807a978ba7f0d3cb9f527dad6c5d4','94146d61170c7a3cc87db9e04be01854'))v(signature,body_hash,definition_hash)LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_proc x WHERE x.oid=to_regprocedure(d.signature)AND md5(x.prosrc)=d.body_hash AND md5(pg_get_functiondef(x.oid))=d.definition_hash)
  THEN RAISE EXCEPTION'workorder_parameterized_financial_definition_drift';END IF;
 END LOOP;
 IF md5(pg_get_functiondef('public.dashboard_admin_live_workorders(jsonb)'::regprocedure))<>'aacc8175b2e85d873ea1573eee9d9ed2'THEN RAISE EXCEPTION'workorder_parameterized_public_wrapper_drift';END IF;
 IF new_count=2 THEN RETURN;END IF;
 SELECT(select md5(coalesce(jsonb_agg(jsonb_build_array(other_proc.oid,to_jsonb(other_proc),pg_get_functiondef(other_proc.oid))order by other_proc.oid),'[]')::text)from pg_proc other_proc where other_proc.pronamespace in('private'::regnamespace,'public'::regnamespace)and other_proc.oid<>all(array['private.dashboard_admin_live_workorders(jsonb)'::regprocedure::oid,'private.dashboard_admin_live_workorder_unique_totals(jsonb,jsonb)'::regprocedure::oid]))INTO other_before;
 SELECT(select md5(coalesce(jsonb_agg(jsonb_build_array(c.oid,to_jsonb(c)-array['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'],
 (select jsonb_agg(to_jsonb(a)order by a.attnum)from pg_attribute a where a.attrelid=c.oid and a.attnum>0),
 (select jsonb_agg(jsonb_build_array(t.oid,to_jsonb(t),pg_get_triggerdef(t.oid))order by t.oid)from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),
 (select jsonb_agg(jsonb_build_array(i.indexrelid,to_jsonb(i),pg_get_indexdef(i.indexrelid))order by i.indexrelid)from pg_index i where i.indrelid=c.oid))order by c.oid),'[]')::text)from pg_class c where c.oid=any(array['public.newar_detail_records','public.newar_detail_platforms','public.ar_workorder_issue_details','public.workorder_deposit_daily']::regclass[]))INTO source_before;
 SELECT(select jsonb_build_object('commonIN',private.prepared_aggregate_dependency_common('IN'),'providerIN',(select jsonb_agg(jsonb_build_array(to_jsonb(native_row),private.provider_snapshot_dependency_token(to_jsonb(native_row)))order by native_row.id)from private.prepared_aggregate_native_catalog()native_row where native_row.country='印度'and native_row.source='newar'and native_row.source_name in('DhaniWin','MAANWIN')),'withdraw',private.withdraw_prepared_dependency()))INTO tokens_before;
 FOR r IN SELECT value FROM jsonb_array_elements(rows)LOOP
  SELECT *INTO p FROM pg_proc WHERE oid=to_regprocedure(r->>'signature');metadata:=to_jsonb(p)-'prosrc';definition:=pg_get_functiondef(p.oid);
  IF position(r->>'before'IN definition)=0 OR position(r->>'before'IN substring(definition FROM position(r->>'before'IN definition)+length(r->>'before')))>0 THEN RAISE EXCEPTION'workorder_parameterized_replacement_not_unique';END IF;
  EXECUTE replace(definition,r->>'before',r->>'after');
  SELECT *INTO p FROM pg_proc WHERE oid=to_regprocedure(r->>'signature');
  IF md5(p.prosrc)IS DISTINCT FROM r->>'newBody'OR md5(pg_get_functiondef(p.oid))IS DISTINCT FROM r->>'newDefinition'OR(to_jsonb(p)-'prosrc')IS DISTINCT FROM metadata THEN RAISE EXCEPTION'workorder_parameterized_postcondition';END IF;
 END LOOP;
 IF other_before IS DISTINCT FROM(select md5(coalesce(jsonb_agg(jsonb_build_array(other_proc.oid,to_jsonb(other_proc),pg_get_functiondef(other_proc.oid))order by other_proc.oid),'[]')::text)from pg_proc other_proc where other_proc.pronamespace in('private'::regnamespace,'public'::regnamespace)and other_proc.oid<>all(array['private.dashboard_admin_live_workorders(jsonb)'::regprocedure::oid,'private.dashboard_admin_live_workorder_unique_totals(jsonb,jsonb)'::regprocedure::oid]))OR source_before IS DISTINCT FROM(select md5(coalesce(jsonb_agg(jsonb_build_array(c.oid,to_jsonb(c)-array['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'],
 (select jsonb_agg(to_jsonb(a)order by a.attnum)from pg_attribute a where a.attrelid=c.oid and a.attnum>0),
 (select jsonb_agg(jsonb_build_array(t.oid,to_jsonb(t),pg_get_triggerdef(t.oid))order by t.oid)from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal),
 (select jsonb_agg(jsonb_build_array(i.indexrelid,to_jsonb(i),pg_get_indexdef(i.indexrelid))order by i.indexrelid)from pg_index i where i.indrelid=c.oid))order by c.oid),'[]')::text)from pg_class c where c.oid=any(array['public.newar_detail_records','public.newar_detail_platforms','public.ar_workorder_issue_details','public.workorder_deposit_daily']::regclass[]))OR tokens_before IS DISTINCT FROM(select jsonb_build_object('commonIN',private.prepared_aggregate_dependency_common('IN'),'providerIN',(select jsonb_agg(jsonb_build_array(to_jsonb(native_row),private.provider_snapshot_dependency_token(to_jsonb(native_row)))order by native_row.id)from private.prepared_aggregate_native_catalog()native_row where native_row.country='印度'and native_row.source='newar'and native_row.source_name in('DhaniWin','MAANWIN')),'withdraw',private.withdraw_prepared_dependency()))THEN RAISE EXCEPTION'workorder_parameterized_unrelated_change';END IF;
END;$pair$;
COMMIT;
